#include <stdio.h>

/* 招牌上写好了交付顺序：先整袋，后吃掉的 */
int fish_left(int total, int eaten) {
    return total - eaten;
}

int main(void) {
    /* 递货顺序摆正：先整袋，后吃掉的 */
    printf("还剩 %d 条\n", fish_left({bag}, {eaten}));
    return 0;
}
